    return G

G = load()
demo_in = np.array(G['Demo pair 1 input'])
demo_out = np.array(G['Demo pair 1 output'])

# Find all maximal rectangular blocks of 2s
def find_rect_blocks(grid):
    h, w = grid.shape
    blocks = []
    visited_2s = set()

    for i in range(h):
        for j in range(w):
            if grid[i,j] == 2 and (i,j) not in visited_2s:
                # Find maximal rectangle starting here
                top = i
                bottom = i
                while bottom < h and grid[bottom, j] == 2:
                    bottom += 1
                bottom -= 1
                left = j
                right = j
                while right + 1 < w and all(grid[r, right+1] == 2 for r in range(top, bottom+1)):
                    right += 1
                new_block = [(r,c) for r in range(top, bottom+1) for c in range(left, right+1)]
                for cell in new_block:
                    visited_2s.add(cell)
                blocks.append((new_block, (top,bottom,left,right)))

    return blocks

