            reason = f"touches {tr-1},{c} above"
            break

    # Check bottom edge
    if not surrounded:
        reason = f"touches {tb+1},{tl} below"
    else:
        for c in range(tl, tc+1):
            if tb < h-1 and demo_in[tb+1, c] != 0:
                surrounded = False
                reason = f"touches {tb+1},{c} below"
                break

    # Check left edge
