        reason = f"touches {tr},{tl-1} left"
    else:
        for r in range(tr, tb+1):
            if tl > 0 and demo_in[r, tl-1] != 0:
                surrounded = False
                reason = f"touches {r},{tl-1} left"
                break

    # Check right edge
