import os
import re

def search_files(root, max_depth=3):
    results = []
    for path, dirs, files in os.walk(root):
        # Limit depth
        if path.count('/') > 7:
            continue
        for f in files:
            rel = os.path.relpath(os.path.join(path, f), root)
            if '.json' in f.lower() and ('grid' in f.lower() or 'input' in f.lower()):
                results.append(rel)
        if len(path.split('/')) > max_depth:
            break
    return results

