import numpy as np

lines_in = [l.split() for l in demo_in_str.strip().split('\n')]
lines_out = [l.split() for l in demo_out_str.strip().split('\n')]
demo_in = np.array([list(map(int, x)) for x in lines_in])
demo_out_true = np.array([list(map(int, x)) for x in lines_out])

horiz_rows = [8]
vert_cols = [7]

# Find all 2-blocks
visited = set()
def dfs(r, c, block_cells):
    stack = [(r, c)]
    while stack:
        cr, cc = stack.pop()
        if (cr, cc) in visited: continue
        visited.add((cr, cc))
        block_cells.append((cr, cc))
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < demo_in.shape[0] and 0 <= nc < demo_in.shape[1]:
                if demo_in[nr][nc] == 2 and (nr, nc) not in visited:
                    stack.append((nr, nc))

all_blocks = []
for i in range(demo_in.shape[0]):
    for j in range(demo_in.shape[1]):
        if demo_in[i][j] == 2 and (i,j) not in visited:
            block_cells = []
            dfs(i, j, block_cells)
            all_blocks.append(block_cells.copy())

print(f"Total blocks: {len(all_blocks)}")

# Build output using new hypothesis
output = demo_in.copy()

# Step 1: Fill marker lines completely
for hr in horiz_rows:
    output[hr, :] = 1
for vc in vert_cols:
    output[:, vc] = 1

# Step 2: Find which 2-cells had 0 above them and mark their block top rows to clear
cells_with_zero_above = [(r,c) for r in range(1, demo_in.shape[0]) 
                              for c in range(demo_in.shape[1])
                              if demo_in[r-1, c] == 0 and demo_in[r, c] == 2]

# Group these cells by their block
block_top_clear = {}  # block_id -> set of cells to clear
for b_idx, block in enumerate(all_blocks):
    min_r = min(cr for cr,_ in block)

    # Check if ANY cell in the top row (min_r) has zero above
    should_clear = any(demo_in[min_r, c] == 2 and demo_in[min_r-1, c] == 0 for c in range(demo_in.shape[1]))

    if should_clear:
        for r,c in block:
            if r == min_r:
                block_top_clear[b_idx] = set()

    # Now check each cell in top row
    for r,c in block:
        if r == min_r and demo_in[r-1,c] == 0:
            block_top_clear[b_idx] = block_top_clear.get(b_idx, set()).union({(r,c)})

# Actually simpler: just find which blocks need top row clearing
clearing_needed = set()
for b_idx, block in enumerate(all_blocks):
    min_r = min(r for r,c in block)
    # Top row needs clearing if ALL cells in top row have 0 above them? 
